/**
 * 路由配置 (admin)
 * 对应后端已实现的 CRUD + Dashboard
 */
import { createRouter, createWebHistory, type RouteRecordRaw } from "vue-router";
import { isLoggedIn } from "@/utils/auth";

const previewMode =
  import.meta.env.DEV && new URLSearchParams(window.location.search).get("preview") === "1";

const routes: RouteRecordRaw[] = [
  {
    path: "/login",
    name: "login",
    component: () => import("@/pages/Login.vue"),
    meta: { title: "登录" },
  },
  {
    path: "/",
    component: () => import("@/layouts/AdminLayout.vue"),
    children: [
      {
        path: "",
        redirect: "/dashboard",
      },
      {
        path: "dashboard",
        name: "dashboard",
        component: () => import("@/pages/Dashboard.vue"),
        meta: { title: "控制台" },
      },
      {
        path: "community",
        name: "community",
        component: () => import("@/pages/community/CommunityOperations.vue"),
        meta: { title: "社区运营" },
      },
      {
        path: "product",
        name: "product",
        component: () => import("@/pages/product/ProductList.vue"),
        meta: { title: "商品管理" },
      },
      {
        path: "/admin/product/product_list",
        redirect: to => ({ path: "/product", query: to.query, hash: to.hash }),
      },
      {
        path: "/admin/product/add_product/:id?",
        redirect: to => ({ path: to.params.id === undefined || to.params.id === "" || to.params.id === "0" ? "/product/create" : `/product/edit/${encodeURIComponent(String(to.params.id))}`, query: to.query, hash: to.hash }),
      },
      {
        path: "product/metadata",
        name: "product-metadata",
        component: () => import("@/pages/product/ProductMetadata.vue"),
        meta: { title: "商品基础资料" },
      },
      {
        path: "product/create",
        name: "product-create",
        component: () => import("@/pages/product/ProductForm.vue"),
        meta: { title: "添加商品" },
      },
      {
        path: "product/edit/:id",
        name: "product-edit",
        component: () => import("@/pages/product/ProductForm.vue"),
        beforeEnter: to => to.params.id === "0" ? { path: "/product/create", query: to.query, hash: to.hash } : true,
        meta: { title: "编辑商品" },
      },
      {
        path: "product/virtual-alerts",
        name: "product-virtual-alerts",
        component: () => import("@/pages/product/VirtualInventoryAlerts.vue"),
        meta: { title: "卡密库存预警" },
      },
      {
        path: "product/virtual/:id",
        name: "product-virtual-inventory",
        component: () => import("@/pages/product/VirtualInventory.vue"),
        meta: { title: "卡密库存" },
      },
      {
        path: "order",
        name: "order",
        component: () => import("@/pages/order/OrderList.vue"),
        meta: { title: "订单管理" },
      },
      {
        path: "order/offline",
        name: "offline-orders",
        component: () => import("@/pages/order/OfflineOrders.vue"),
