 for(const entry of proof.sources){
  it(`pins complete actual source and complete predecessor ${entry.file}`,()=>{const current=read(entry.file);expect(sha(current)).toBe(entry.after_sha256);expect(sha(reverseBrowserLogSource(entry.file,current))).toBe(entry.before_sha256);expect(sha(readBrowserLogPredecessor(resolve(root,entry.file)))).toBe(entry.before_sha256);expect(readBrowserLogPredecessor(resolve(root,entry.file),'utf8')).toBe(entry.edits[0]!.before_source);});
  it(`rejects unreviewed, truncated and duplicated source ${entry.file}`,()=>{const raw=read(entry.file);for(const value of [raw+'\n// unreviewed\n',raw.slice(1),raw+raw])expect(()=>reverseBrowserLogSource(entry.file,value)).toThrow();});
